  ('9f0b3a83-8b66-4b20-a9a5-f5919cfc8c46', 'Handbags', 'handbags', 'Structured totes, soft hobos and everyday carry-alls in full-grain leather.', '/images/products/the-tulip-tote/tan-front.webp', 1, true),
  ('9007b495-6a60-41ea-ae57-ae27ff750a5c', 'Purses', 'purses', 'Pouches and clutches for evenings, errands and everything in between.', '/images/products/the-petal-clutch/ivory-front.webp', 2, true),
  ('ce2d7379-8c10-4554-a554-969318427356', 'Wallets', 'wallets', 'Slim, considered wallets that age beautifully with you.', '/images/products/the-fold-wallet/tan-front.webp', 3, true),
  ('fdad9800-4d9d-4e89-aa89-bceaefa9b653', 'Coin Purses', 'coin-purses', 'Little leather keepers for coins, keys and small treasures.', '/images/products/the-pebble-coin-purse/tan-front.webp', 4, true),
  ('30ec7886-5235-4cd5-aa9e-1978610c7d2f', 'Men''s Essentials', 'mens-essentials', 'Bifolds, messengers and folios with quiet, lasting design.', '/images/products/the-voyager-messenger/dark-brown-front.webp', 5, true),
  ('968ea801-1344-49d0-af32-e8afb0de0ad6', 'Accessories', 'accessories', 'Charms, key fobs and finishing touches.', '/images/products/the-daisy-bag-charm/ivory-front.webp', 6, true)
