  ('00038fbd-ba16-431c-aa3d-d3bfb8a01896', 'Everyday Chic', 'everyday-chic', 'Soft shapes for coffee runs, lunches and long walks.', '/images/products/the-crescent-bag/cognac-front.webp', 2, true),
