insert into public.collections (id, name, slug, description, image_url, sort_order, is_visible) values
  ('ab8a606c-9e56-442b-a902-94e221351391', 'Heritage', 'heritage', 'Timeless silhouettes inspired by classic leathercraft.', null, 1, true),
