insert into public.products (id, name, slug, short_description, description, category_id, collection_id, material, dimensions, width_cm, height_cm, depth_cm, strap_drop_cm, weight_g, care_instructions, price, compare_at_price, cost_price, gst_rate, status, is_featured, is_trending, is_new, has_spin, low_stock_threshold, total_sold, sort_order, created_at) values
  ('52fc7e10-80cd-4093-a414-05fe41eaa449', 'The Tulip Tote', 'the-tulip-tote', 'A modern classic, inspired by the elegance of a tulip.', '<p>Our signature tote, shaped like a tulip in bloom. Cut from a single hide of full-grain, vegetable-tanned leather, it softens and deepens in colour with every year you carry it.</p><p>Inside, a suede-lined main compartment fits a 13" laptop, with a zip pocket and two slip pockets for the things you reach for most. A magnetic closure keeps everything secure without slowing you down.</p><ul><li>Full-grain vegetable-tanned leather</li><li>Fits a 13" laptop</li><li>Interior zip pocket + 2 slip pockets</li><li>Hand-stitched handle tabs</li></ul>', '9f0b3a83-8b66-4b20-a9a5-f5919cfc8c46', 'b0bf88ac-3af1-4f1f-a00d-534ae309faf5', 'Full-grain vegetable-tanned leather, suede lining', '34 × 28 × 14 cm', 34, 28, 14, 22, 820, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 8990, null, 3600, 18, 'published', true, true, false, true, 5, 412, 1, '2026-09-22T06:00:00.000Z'),
  ('2a504dcd-5cd4-455a-a1be-5a3b0fe6cd40', 'The Crescent Bag', 'the-crescent-bag', 'A soft half-moon shoulder bag that sits beautifully against you.', '<p>The Crescent curves gently under the arm, holding its shape while staying soft to the touch. A slim adjustable strap and a single zip compartment make it the bag you''ll reach for from morning to evening.</p><ul><li>Full-grain nappa leather</li><li>YKK zip closure</li><li>Interior slip pocket</li><li>Adjustable strap</li></ul>', '9f0b3a83-8b66-4b20-a9a5-f5919cfc8c46', 'b0bf88ac-3af1-4f1f-a00d-534ae309faf5', 'Full-grain nappa leather, cotton twill lining', '36 × 20 × 9 cm', 36, 20, 9, 26, 540, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 7990, null, 3100, 18, 'published', true, true, false, false, 5, 268, 2, '2026-09-21T06:00:00.000Z'),
  ('3760a9cf-7e3b-4220-a4c3-ac29a953b382', 'The Mini Crossbody', 'the-mini-crossbody', 'Hands-free and perfectly sized for your phone, cards and keys.', '<p>A compact crossbody with a softly rounded flap and a brushed-gold turn-lock. The long adjustable strap lets you wear it across the body or on the shoulder.</p><ul><li>Fits a large smartphone</li><li>Turn-lock closure</li><li>Card slot under the flap</li><li>Removable, adjustable strap</li></ul>', '9f0b3a83-8b66-4b20-a9a5-f5919cfc8c46', 'b4803f7c-81fe-44e3-a2fd-faca691f8959', 'Pebbled full-grain leather, microsuede lining', '21 × 15 × 7 cm', 21, 15, 7, 58, 390, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 5960, null, 2300, 18, 'published', false, true, false, false, 5, 389, 3, '2026-09-20T06:00:00.000Z'),
  ('c07f25c7-d863-46aa-a738-6e9dad45d7a8', 'The Weave Pouch', 'the-weave-pouch', 'Hand-woven leather strips, finished with a wrist loop.', '<p>Each Weave Pouch takes our artisans over four hours to hand-weave. Carry it as a clutch, or slip it inside a tote to keep your essentials together.</p><ul><li>Hand-woven leather</li><li>Zip closure</li><li>Detachable wrist loop</li></ul>', '9007b495-6a60-41ea-ae57-ae27ff750a5c', 'ab8a606c-9e56-442b-a902-94e221351391', 'Hand-woven full-grain leather', '24 × 16 × 3 cm', 24, 16, 3, null, 210, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 3490, null, 1300, 18, 'published', false, true, false, false, 5, 174, 4, '2026-09-19T06:00:00.000Z'),
  ('fec90350-8119-4275-a5d0-2502ddde7e5f', 'The Fold Wallet', 'the-fold-wallet', 'A slim tri-fold with room for cards, notes and coins.', '<p>Thoughtfully compact, the Fold Wallet keeps eight cards, folded notes and a zip coin pocket in a shape that slips into any bag.</p><ul><li>8 card slots</li><li>Zip coin pocket</li><li>Snap closure</li></ul>', 'ce2d7379-8c10-4554-a554-969318427356', 'b4803f7c-81fe-44e3-a2fd-faca691f8959', 'Full-grain leather', '12 × 10 × 2.5 cm', 12, 10, 2.5, null, 140, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 2990, null, 1050, 18, 'published', false, true, false, false, 5, 356, 5, '2026-09-18T06:00:00.000Z'),
  ('e8a9e207-6fcb-4454-a30f-5679ceda3606', 'The Heritage Satchel', 'the-heritage-satchel', 'A structured top-handle satchel with twin buckle pockets.', '<p>Inspired by the doctors'' bags of the 1920s, the Heritage Satchel has a rolled top handle, a detachable shoulder strap and two buckled front pockets.</p><ul><li>Fits a 14" laptop</li><li>Detachable shoulder strap</li><li>Two buckled front pockets</li><li>Protective metal feet</li></ul>', '9f0b3a83-8b66-4b20-a9a5-f5919cfc8c46', 'ab8a606c-9e56-442b-a902-94e221351391', 'Full-grain vegetable-tanned leather, canvas lining', '36 × 27 × 15 cm', 36, 27, 15, 45, 1050, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 10490, 11990, 4300, 18, 'published', true, false, false, false, 5, 97, 6, '2026-09-17T06:00:00.000Z'),
  ('fa281127-a213-440a-a299-b86161879414', 'The Pebble Coin Purse', 'the-pebble-coin-purse', 'A softly domed kiss-lock purse for coins and keepsakes.', '<p>A small joy. The Pebble''s brushed-gold kiss-lock clicks closed with a satisfying snap, keeping coins, earrings or keys safely in one place.</p>', 'fdad9800-4d9d-4e89-aa89-bceaefa9b653', 'ab8a606c-9e56-442b-a902-94e221351391', 'Full-grain leather, brushed-brass frame', '11 × 9 × 4 cm', 11, 9, 4, null, 80, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 1490, null, 520, 18, 'published', false, false, false, false, 5, 241, 7, '2026-09-16T06:00:00.000Z'),
  ('85560e83-6802-4b24-ab88-9dcd70318cbe', 'The Petal Clutch', 'the-petal-clutch', 'An envelope clutch with a softly scalloped petal flap.', '<p>For dinners, weddings and evenings out. The Petal Clutch has a magnetic flap, a card slot and an optional chain strap tucked inside.</p>', '9007b495-6a60-41ea-ae57-ae27ff750a5c', 'b0bf88ac-3af1-4f1f-a00d-534ae309faf5', 'Smooth calf leather', '26 × 15 × 4 cm', 26, 15, 4, null, 260, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 4290, null, 1700, 18, 'published', false, false, false, false, 5, 88, 8, '2026-09-15T06:00:00.000Z'),
  ('eea2651e-4549-4d69-a0ae-456076dd2383', 'The Bloom Bucket Bag', 'the-bloom-bucket-bag', 'A drawstring bucket bag that opens like a flower.', '<p>Roomy yet light, the Bloom cinches closed with a leather drawstring and carries on the shoulder or by its short top handle.</p>', '9f0b3a83-8b66-4b20-a9a5-f5919cfc8c46', 'b0bf88ac-3af1-4f1f-a00d-534ae309faf5', 'Full-grain tumbled leather', '25 × 27 × 18 cm', 25, 27, 18, 30, 610, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 7490, null, 2950, 18, 'published', false, false, true, false, 5, 46, 9, '2026-10-24T06:00:00.000Z'),
  ('e5d9ac6a-5541-4eab-a943-044802f74ac1', 'The Card Sleeve', 'the-card-sleeve', 'Four card slots and a centre pocket in a whisper-slim sleeve.', '<p>Our slimmest piece. Edge-painted by hand and stitched with waxed linen thread.</p>', 'ce2d7379-8c10-4554-a554-969318427356', 'b4803f7c-81fe-44e3-a2fd-faca691f8959', 'Full-grain leather, hand-painted edges', '10.5 × 7.5 × 0.6 cm', 10.5, 7.5, 0.6, null, 35, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 1690, null, 560, 18, 'published', false, false, true, false, 5, 198, 10, '2026-10-23T06:00:00.000Z'),
  ('3d06b121-98f4-48a2-a578-84e31837ec7c', 'The Atlas Bifold', 'the-atlas-bifold', 'A classic bifold with six card slots and a note pocket.', '<p>A gentleman''s essential, built to last for decades and look better every year.</p>', '30ec7886-5235-4cd5-aa9e-1978610c7d2f', 'b4803f7c-81fe-44e3-a2fd-faca691f8959', 'Full-grain crazy-horse leather', '11.5 × 9.5 × 1.5 cm', 11.5, 9.5, 1.5, null, 95, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 2790, null, 980, 18, 'published', false, false, false, false, 5, 233, 11, '2026-09-12T06:00:00.000Z'),
  ('76d5e5c4-11a0-429d-aa51-6a6e47491267', 'The Voyager Messenger', 'the-voyager-messenger', 'A roomy messenger with twin buckles and a padded laptop sleeve.', '<p>The Voyager carries a 15" laptop, documents and a day''s worth of essentials. Brass buckles hide quick-release magnetic catches.</p>', '30ec7886-5235-4cd5-aa9e-1978610c7d2f', 'ab8a606c-9e56-442b-a902-94e221351391', 'Full-grain crazy-horse leather, cotton canvas lining', '40 × 30 × 11 cm', 40, 30, 11, 60, 1450, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 11990, null, 4900, 18, 'published', true, false, false, false, 5, 64, 12, '2026-09-11T06:00:00.000Z'),
  ('f5ab16fd-4265-4b46-a65d-97279feca7c0', 'The Keystone Key Fob', 'the-keystone-key-fob', 'A teardrop leather key fob on a solid brass ring.', '<p>A small, satisfying piece to keep your keys together and easy to find.</p>', '968ea801-1344-49d0-af32-e8afb0de0ad6', 'b4803f7c-81fe-44e3-a2fd-faca691f8959', 'Full-grain leather, solid brass', '4 × 11 × 0.8 cm', 4, 11, 0.8, null, 30, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 990, null, 280, 18, 'published', false, false, false, false, 5, 140, 13, '2026-09-10T06:00:00.000Z'),
  ('7b352501-3c32-418e-a3be-0ed3711dc668', 'The Laptop Folio', 'the-laptop-folio', 'A zip-around folio for a 14" laptop, charger and notebook.', '<p>Felt-lined and softly padded, with a slim cut-out handle and a front document pocket.</p>', '30ec7886-5235-4cd5-aa9e-1978610c7d2f', 'b4803f7c-81fe-44e3-a2fd-faca691f8959', 'Full-grain leather, wool felt lining', '36 × 26 × 3 cm', 36, 26, 3, null, 520, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 6490, null, 2500, 18, 'published', false, false, true, false, 5, 31, 14, '2026-10-19T06:00:00.000Z'),
  ('ae3fc644-73b3-4319-a09e-08bef3794ffb', 'The Daisy Bag Charm', 'the-daisy-bag-charm', 'A hand-cut leather daisy to make any bag your own.', '<p>Clip it on a handle or keyring. Each petal is cut and edge-painted by hand.</p>', '968ea801-1344-49d0-af32-e8afb0de0ad6', 'b0bf88ac-3af1-4f1f-a00d-534ae309faf5', 'Full-grain leather, brushed-brass clasp', '7 × 12 × 1 cm', 7, 12, 1, null, 25, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 1290, null, 380, 18, 'published', false, false, true, false, 5, 162, 15, '2026-10-18T06:00:00.000Z'),
  ('e641a8ec-5759-4d7b-ac91-25d665e689dd', 'The Zip Coin Pouch', 'the-zip-coin-pouch', 'A soft zip pouch for coins, earphones and small things.', '<p>Simple and useful. A leather pull makes it easy to open with one hand.</p>', 'fdad9800-4d9d-4e89-aa89-bceaefa9b653', 'b4803f7c-81fe-44e3-a2fd-faca691f8959', 'Full-grain leather', '12 × 9 × 2 cm', 12, 9, 2, null, 50, 'Wipe gently with a soft, dry cloth. Keep away from direct sunlight, heat and moisture. Condition every 3–6 months with a neutral leather balm. Store in the dust bag provided, stuffed lightly with tissue to hold its shape.', 1290, null, 430, 18, 'published', false, false, true, false, 5, 23, 16, '2026-10-17T06:00:00.000Z')
