insert into public.reviews (id, product_id, author_name, rating, title, body, status, is_verified, admin_reply, created_at) values
  ('d5c04812-62c8-467d-a0a3-28b43c81bd4f', '52fc7e10-80cd-4093-a414-05fe41eaa449', 'Prakkanthi R.', 5, 'Worth every rupee', 'The leather is buttery and the stitching is perfect. Fits my 13" MacBook with room to spare. I get compliments every day.', 'approved', true, null, '2026-10-26T06:00:00.000Z'),
  ('d6c049a5-61c8-44ea-a1a3-2a473b81bbbc', '52fc7e10-80cd-4093-a414-05fe41eaa449', 'Ananya S.', 5, 'My everyday bag now', 'Beautiful colour, even better in person. It has already started to soften after a month.', 'approved', true, null, '2026-10-23T06:00:00.000Z'),
  ('d3c044ec-60c8-4357-a2a3-2bda3e81c075', '52fc7e10-80cd-4093-a414-05fe41eaa449', 'Meera K.', 4, 'Lovely, slightly heavy', 'Gorgeous bag. It''s a little heavier than my old canvas tote, but the quality is on another level.', 'approved', true, 'Thank you, Meera! The leather softens a little with use, which makes it feel lighter on the shoulder.', '2026-10-20T06:00:00.000Z'),
  ('d4c0467f-5fc8-41c4-a3a3-2d6d3d81bee2', '2a504dcd-5cd4-455a-a1be-5a3b0fe6cd40', 'Divya N.', 5, 'So elegant', 'The burgundy is rich and the shape sits so nicely on the shoulder.', 'approved', true, null, '2026-10-17T06:00:00.000Z'),
  ('d1c041c6-5ec8-4031-aca3-22683881b703', '3760a9cf-7e3b-4220-a4c3-ac29a953b382', 'Rhea P.', 5, 'Perfect travel bag', 'Took it to Jaipur — hands-free and fits everything I need.', 'approved', true, null, '2026-10-14T06:00:00.000Z'),
  ('d2c04359-5dc8-4e9e-ada3-23fb3781b570', 'fec90350-8119-4275-a5d0-2502ddde7e5f', 'Karthik V.', 5, 'Great gift', 'Bought it for my wife, she loves it. Beautiful packaging too.', 'approved', true, null, '2026-10-11T06:00:00.000Z'),
  ('cfc03ea0-5cc8-4d0b-aea3-258e3a81ba29', 'e8a9e207-6fcb-4454-a30f-5679ceda3606', 'Lakshmi M.', 5, 'Heirloom quality', 'This is the kind of bag you pass down. Absolutely stunning.', 'approved', true, null, '2026-10-08T06:00:00.000Z')
