insert into public.pages (id, slug, title, subtitle, content, hero_image, seo_title, seo_description, is_published, updated_at) values
  ('f5266f0b-dc17-49b8-a722-26598359a096', 'our-story', 'Our Story', 'More than a bag. A part of your story.', '<h2>Made slowly, in Chennai</h2><p>seicase began in a small studio in Chennai with a simple belief: the things you carry every day should be made with care, and made to last. We work with a close-knit team of artisans who have spent decades working with leather — cutting, stitching and finishing each piece by hand.</p><h2 id="process">Our process</h2><p>Every bag starts as a single full-grain hide from an LWG-certified tannery in Tamil Nadu. We hand-select each hide, cut panels to minimise waste, and stitch with waxed linen thread that grows stronger with time. Edges are painted and burnished in several layers — a slow step that gives every piece its quiet, finished look.</p><h2>Thoughtful design</h2><p>We design for real days: a laptop that needs a home, a phone that needs a pocket, keys that need finding. Then we pare everything back until only what matters remains.</p><h2>Made to stay</h2><p>Good leather gets better with age. With a little care, your seicase will soften, deepen in colour and carry the marks of your story for years to come. If anything ever needs attention, our studio is here to help.</p>', '/images/banners/crafted.webp', null, 'More than a bag. A part of your story.', true, '2026-11-01T00:00:00.000Z'),
  ('4ef7565f-716e-4662-a9a3-94d9ce13d3bc', 'care-guide', 'Care Guide', 'A little care goes a long way.', '<h2>Everyday care</h2><ul><li>Wipe your bag with a soft, dry cloth after use.</li><li>Keep it away from direct sunlight, radiators and damp places.</li><li>Avoid contact with oils, lotions and perfume.</li></ul><h2>If it gets wet</h2><p>Blot gently with a dry cloth — never rub. Let it air dry naturally at room temperature, away from heat. Stuff with tissue to help it keep its shape.</p><h2>Conditioning</h2><p>Every 3–6 months, apply a small amount of neutral leather balm with a soft cloth in circular motions. Let it absorb for an hour, then buff lightly.</p><h2>Storage</h2><p>Store your bag in its dust bag, lightly stuffed with tissue paper. Avoid plastic covers, which trap moisture.</p><h2>Patina</h2><p>Vegetable-tanned leather darkens and develops a soft sheen over time. This patina is unique to you — it''s a sign of a life well carried.</p>', null, null, 'A little care goes a long way.', true, '2026-11-01T00:00:00.000Z'),
  ('19ca3ed6-0b58-44c9-a056-972c40f8e6cf', 'shipping-policy', 'Shipping Policy', 'Free shipping on orders above ₹2,000.', '<h2>Dispatch</h2><p>We dispatch orders within 1–2 business days from Chennai. Orders placed on Sundays and public holidays are dispatched the next business day.</p><h2>Delivery times</h2><ul><li>Metro cities: 2–4 business days</li><li>Rest of India: 4–7 business days</li></ul><h2>Shipping charges</h2><p>Shipping is free on orders above ₹2,000. A flat fee of ₹99 applies to orders below ₹2,000. Cash on Delivery orders carry a ₹49 handling fee.</p><h2>Tracking</h2><p>You''ll receive an email with your tracking number and courier link as soon as your order ships. You can also track it any time from My Orders.</p><h2>Delays</h2><p>Occasionally, weather or courier delays may affect delivery. If your order is taking longer than expected, please contact us and we''ll look into it right away.</p>', null, null, 'Free shipping on orders above ₹2,000.', true, '2026-11-01T00:00:00.000Z'),
  ('8445b48d-c458-411e-a589-e3fb3aa18b74', 'returns-and-exchanges', 'Returns & Exchanges', 'Easy 15-day returns.', '<h2>Our promise</h2><p>If you''re not completely happy with your purchase, you can return or exchange it within 15 days of delivery.</p><h2>Conditions</h2><ul><li>Items must be unused and in their original condition.</li><li>Include all tags, the dust bag and packaging.</li><li>Bags personalised with an attached charm can be exchanged but not refunded.</li></ul><h2>How to request a return</h2><ol><li>Log in and open <strong>My Orders</strong>.</li><li>Choose the order and tap <strong>Request Return / Exchange</strong>.</li><li>Tell us why, and add photos if something is wrong.</li><li>We''ll arrange a free pickup within 2–3 business days.</li></ol><h2>Refunds</h2><p>Once your return reaches our studio and passes inspection, we''ll refund your original payment method within 5–7 business days. COD refunds are made to your bank account or UPI ID.</p><h2>Damaged or incorrect items</h2><p>If your order arrives damaged or incorrect, contact us within 48 hours with photos and we''ll make it right immediately.</p>', null, null, 'Easy 15-day returns.', true, '2026-11-01T00:00:00.000Z'),
  ('e1d5a476-25fd-440f-aa50-db605b1dfaf1', 'privacy-policy', 'Privacy Policy', 'How we collect, use and protect your information.', '<p>seicase ("we", "us") respects your privacy. This policy explains what information we collect when you use seicase.com and how we use it, in line with India''s Digital Personal Data Protection Act, 2023.</p><h2>Information we collect</h2><ul><li><strong>Account and order details</strong> — name, email, phone number, shipping and billing addresses.</li><li><strong>Payment information</strong> — processed securely by Razorpay. We never receive or store full card numbers.</li><li><strong>Usage data</strong> — pages viewed, products browsed, device type and approximate location (city level), collected through our own first-party analytics to improve the store.</li></ul><h2>How we use it</h2><ul><li>To process and deliver your orders and handle returns.</li><li>To send order updates and, if you opt in, our newsletter.</li><li>To improve our products, website and customer service.</li><li>To prevent fraud and keep the store secure.</li></ul><h2>Sharing</h2><p>We share information only with partners who help us run the store — payment (Razorpay), delivery couriers, email (Resend) and hosting (Vercel, Supabase). We never sell your personal data.</p><h2>Your choices</h2><p>You can update your details from your account, unsubscribe from emails at any time, or ask us to delete your data by writing to hello@seicase.com.</p><h2>Cookies</h2><p>We use essential cookies to keep you signed in and remember your bag. Analytics data is stored with an anonymous session id.</p><h2>Contact</h2><p>For any privacy questions, contact our Grievance Officer at hello@seicase.com or 12, Fashion Street, Chennai 600001.</p>', null, null, 'How we collect, use and protect your information.', true, '2026-11-01T00:00:00.000Z'),
  ('235915ba-eff4-47bb-a5dc-d670c21afe51', 'terms-of-service', 'Terms of Service', 'The terms that apply when you shop with us.', '<h2>About these terms</h2><p>By using seicase.com and placing an order, you agree to these terms. Please read them carefully.</p><h2>Products and pricing</h2><p>All prices are in Indian Rupees (₹) and include GST. Leather is a natural material, so small variations in grain, colour and texture are normal and make every piece unique. We do our best to display colours accurately, but screens vary.</p><h2>Orders</h2><p>Your order is confirmed once payment is received (or, for COD, once it is placed). We may cancel an order in rare cases — for example, if an item is out of stock or a pricing error occurs — and will refund you in full.</p><h2>Payments</h2><p>Online payments are processed by Razorpay. By paying, you also agree to Razorpay''s terms.</p><h2>Shipping, returns and refunds</h2><p>Please see our Shipping Policy and Returns &amp; Exchanges pages, which form part of these terms.</p><h2>Intellectual property</h2><p>All content on this site — designs, images, text and the seicase name — belongs to seicase and may not be used without permission.</p><h2>Liability</h2><p>To the extent permitted by law, our liability for any order is limited to the amount you paid for it.</p><h2>Governing law</h2><p>These terms are governed by the laws of India, and disputes are subject to the courts of Chennai, Tamil Nadu.</p>', null, null, 'The terms that apply when you shop with us.', true, '2026-11-01T00:00:00.000Z')
insert into public.journal_posts (id, title, slug, excerpt, content, cover_image, author, tags, status, published_at, seo_title, seo_description) values
  ('f2ad7939-e3d1-4c90-acf0-eba756b11eb6', 'The Beauty of Patina: How Leather Tells Your Story', 'the-beauty-of-patina', 'Why vegetable-tanned leather gets better with every year — and how to help it age gracefully.', '<p>Run your hand over a well-loved leather bag and you''ll feel it: a softness, a warmth, a sheen that no new bag has. That''s patina — the slow change that happens as leather meets sunlight, the oils of your hands, and the rhythm of your days.</p><h2>What causes patina?</h2><p>Vegetable-tanned leather is tanned with natural tannins from tree bark. Unlike chrome-tanned leather, it stays ''alive'' — it absorbs light and oils and darkens gradually.</p><h2>How to encourage it</h2><ul><li>Carry it often. Use is the best conditioner.</li><li>Let it see a little sunlight.</li><li>Condition lightly every few months.</li></ul><p>Your bag will never look exactly like anyone else''s. That''s the point.</p>', '/images/journal/patina.webp', 'The seicase Studio', array['Care', 'Craft']::text[], 'published', '2026-10-12T05:30:00.000Z', null, null),
  ('eab296a5-a41d-4062-af4e-865bfcb241e8', 'Inside Our Chennai Studio', 'inside-our-chennai-studio', 'Meet the artisans who cut, stitch and finish every seicase piece by hand.', '<p>Our studio sits on a quiet street in Chennai, filled with the smell of leather and the steady rhythm of sewing machines. Here, a team of twelve artisans brings every seicase design to life.</p><h2>From hide to handle</h2><p>Each hide is inspected under natural light before cutting. Panels are cut by hand to make the most of every hide, then skived, glued and stitched. Edges are painted up to five times, sanded between each coat.</p><h2>Small batches, by design</h2><p>We make in small batches so every piece gets the attention it deserves — and so nothing goes to waste.</p>', '/images/journal/studio.webp', 'The seicase Studio', array['Craft', 'Behind the scenes']::text[], 'published', '2026-09-20T05:30:00.000Z', null, null),
  ('c51c1271-5b98-4ace-af08-65b30f93dc08', 'What Fits in the Tulip Tote?', 'what-fits-in-the-tulip-tote', 'A 13" laptop, a water bottle, a book and more — we packed it for a full workday.', '<p>The Tulip Tote is our most-loved bag, and the question we''re asked most is simple: what fits?</p><h2>A full workday, packed</h2><ul><li>13" laptop and charger</li><li>A 500ml water bottle</li><li>A paperback and a notebook</li><li>The Fold Wallet and Pebble Coin Purse</li><li>Sunglasses, lip balm and keys in the inner pockets</li></ul><p>And it still closes neatly with its magnetic snap.</p>', '/images/journal/what-fits.webp', 'The seicase Studio', array['Styling']::text[], 'published', '2026-08-30T05:30:00.000Z', null, null)
insert into public.faqs (id, question, answer, category, sort_order, is_popular, is_visible) values
  ('61521353-c63f-46cc-a0ef-2f551a16f556', 'How long does shipping take?', 'Orders are dispatched within 1–2 business days from our Chennai studio. Delivery takes 2–4 business days to metro cities and 4–7 business days to the rest of India. You''ll receive a tracking link by email as soon as your order ships.', 'Shipping', 1, true, true),
  ('ea049e33-47a5-4f72-abc7-6c7505655904', 'Is shipping free?', 'Yes — shipping is free on all orders above ₹2,000. A flat ₹99 shipping fee applies to smaller orders.', 'Shipping', 2, true, true),
  ('85d5573f-e834-4858-ab1b-ef7d6badb38e', 'Do you offer Cash on Delivery?', 'Yes, Cash on Delivery is available across most pincodes in India for orders up to ₹15,000. A small COD handling fee of ₹49 applies.', 'Shipping', 3, false, true),
  ('02b093ae-33d8-4581-ad45-269c9e17e3d7', 'Do you ship internationally?', 'We currently ship within India only. International shipping is coming soon — join our newsletter to be the first to know.', 'Shipping', 4, false, true),
  ('5d7eceda-4df9-4ed9-a3aa-b87cd49d2ceb', 'Can I return or exchange my order?', 'Of course. You can request a return or exchange within 15 days of delivery from My Orders in your account. Items must be unused, with tags and the dust bag included.', 'Returns', 1, true, true),
  ('e6ee747c-e890-4b2d-ae72-fa8acf0ea993', 'What is your return policy?', 'We offer easy 15-day returns. Once we receive and inspect your return, refunds are issued to your original payment method within 5–7 business days. For COD orders, we refund to your bank account or UPI ID.', 'Returns', 2, true, true),
  ('0f3443df-607f-4886-a7e3-ffe5a2832694', 'Are charms and sale items returnable?', 'Personalised items (bags with an attached charm) can be exchanged but not refunded. Sale items can be returned within 15 days like any other order.', 'Returns', 3, false, true),
  ('668bf6aa-6600-4dc1-ab93-fed4874a8abb', 'How do I track my order?', 'Log in and visit My Orders, then tap Track Order to see each step from dispatch to delivery. Guests can use the tracking link in their shipping email.', 'Orders', 1, true, true),
  ('0ba395bc-dca6-4d57-ac1b-44c23b4556cd', 'Can I cancel my order?', 'You can cancel any order that hasn''t shipped yet from My Orders, or by contacting us. Refunds for prepaid orders are processed immediately.', 'Orders', 2, false, true),
  ('e89e5686-674d-4dcd-a6ab-11f0ec3cc1b7', 'Which payment methods do you accept?', 'We accept UPI, all major credit and debit cards, net banking and popular wallets through Razorpay, as well as Cash on Delivery.', 'Payments', 1, false, true),
  ('3cf4a7a8-6f2d-4f31-aa67-a2ded2925407', 'Is it safe to pay on seicase?', 'Yes. Payments are processed by Razorpay, a PCI-DSS compliant gateway. We never see or store your card details.', 'Payments', 2, false, true),
  ('a07f12d6-0bfe-4cef-aee7-df141b7c344d', 'How do I care for my leather bag?', 'Wipe with a soft dry cloth, keep away from direct heat and water, and condition every few months with a neutral leather balm. Store it in its dust bag when not in use.', 'Product Care', 1, true, true),
  ('e389207b-1de6-438e-aad6-2a69023205c4', 'Will the colour change over time?', 'Yes, beautifully. Our vegetable-tanned leathers develop a rich patina with use and sunlight — that''s part of their character.', 'Product Care', 2, false, true),
  ('64583502-4590-4e49-ae18-076ce103e7ab', 'Is your leather genuine?', 'Every seicase piece is made from genuine full-grain or top-grain leather sourced from LWG-certified tanneries in Tamil Nadu.', 'Product Care', 3, false, true)
